import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { replyComment } from "../handlers/replyComment";
import type { ApiError } from "../runtime/client";
import type { ReplyCommentRequest } from "../types/ReplyCommentRequest";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePostCommentEntityType } from "../types/SpacePostCommentEntityType";
import type { SpacePostEntityType } from "../types/SpacePostEntityType";

type Data = Awaited<ReturnType<typeof replyComment>>;
type Vars = { spaceId: SpacePartition; discussionSk: SpacePostEntityType; commentSk: SpacePostCommentEntityType; req: ReplyCommentRequest };

export function useReplyComment(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => replyComment(vars.spaceId, vars.discussionSk, vars.commentSk, vars.req),
    ...options,
  });
}
